#!/bin/sh
# Generated by Strategy for counter -- do not hand-edit
set -eu
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
JAIL=counter
APP=counter
JAIL_IP=10.20.0.3
JROOT="/jails/${JAIL}"
FREEBSD_VERSION="$(freebsd-version -u | cut -d- -f1-2)"
log() { echo "==> [${JAIL}] $*"; }
if [ -d "${JROOT}/opt/${APP}" ] && [ ! -L "${JROOT}/opt/${APP}" ]; then
  echo "${JAIL}: /opt/${APP} is a directory, the old pre-release layout; refusing to bootstrap over it" >&2
  exit 1
fi
service jail stop "$JAIL" 2>/dev/null || true
if [ ! -f "${JROOT}/bin/sh" ]; then
  mkdir -p "$JROOT"
  fetch -o /tmp/base.txz \
    "https://download.freebsd.org/releases/amd64/${FREEBSD_VERSION}/base.txz"
  tar -xpf /tmp/base.txz -C "$JROOT"
  rm /tmp/base.txz
fi
chflags noschg "${JROOT}/etc/resolv.conf" 2>/dev/null || true
echo "nameserver 1.1.1.1" >"${JROOT}/etc/resolv.conf"
chflags schg "${JROOT}/etc/resolv.conf"
cp /etc/localtime "${JROOT}/etc/localtime"
mkdir -p "${JROOT}/opt/.infra-releases" "${JROOT}/var/db/${APP}" \
  "${JROOT}/etc/${APP}" "${JROOT}/var/log/${APP}" "${JROOT}/var/run/${APP}"
grep -q "syslogd_enable" "${JROOT}/etc/rc.conf" 2>/dev/null || cat >>"${JROOT}/etc/rc.conf" <<'EOF'
syslogd_enable="NO"
sendmail_enable="NONE"
EOF
ZFS_DATASET=zroot/counter
HOST_DATA_DIR="${JROOT}/var/db/counter"
if ! zfs list -H -o name "$ZFS_DATASET" >/dev/null 2>&1; then
  zfs create -o mountpoint="$HOST_DATA_DIR" "$ZFS_DATASET"
elif [ "$(zfs get -H -o value mountpoint "$ZFS_DATASET")" != "$HOST_DATA_DIR" ]; then
  echo "counter: ${ZFS_DATASET} mountpoint is not ${HOST_DATA_DIR}; refusing to move existing data" >&2
  exit 1
fi
if [ "$(zfs get -H -o value mounted "$ZFS_DATASET")" != "yes" ]; then
  echo "counter: mounting persistent dataset ${ZFS_DATASET}"
  zfs mount "$ZFS_DATASET" || { echo "counter: failed to mount ${ZFS_DATASET}" >&2; exit 1; }
fi
if [ "$(zfs get -H -o value mounted "$ZFS_DATASET")" != "yes" ] || [ ! -d "$HOST_DATA_DIR" ]; then
  echo "counter: ${ZFS_DATASET} is not mounted at ${HOST_DATA_DIR}; refusing to start jail" >&2
  exit 1
fi
grep -q "^${JAIL}[[:space:]]*{" /etc/jail.conf 2>/dev/null || cat >>/etc/jail.conf <<EOF

${JAIL} {
    path          = /jails/${JAIL};
    host.hostname = ${JAIL}.local;
    ip4.addr      = lo1|${JAIL_IP}/32;
    exec.start    = "/bin/sh /etc/rc";
    exec.stop     = "/bin/sh /etc/rc.shutdown";
    exec.clean;
    mount.devfs;
    allow.raw_sockets = 0;
    allow.sysvipc    = 0;
}
EOF
sysrc -n jail_list | grep -qw "$JAIL" || sysrc jail_list+=" ${JAIL}"
sysrc jail_enable="YES"
service jail start "$JAIL" 2>/dev/null || service jail restart "$JAIL"
jexec "$JAIL" pkg bootstrap -y
jexec "$JAIL" pkg install -y ocaml-opam bash gmake pkgconf sqlite3 gmp ca_root_nss git
jexec "counter" pw useradd -n "counter" -d "/var/db/counter" -s /usr/sbin/nologin \
  -c "counter service user" 2>/dev/null || true
jexec "counter" chown -R "counter:counter" "/var/db/counter" "/var/log/counter" "/var/run/counter"
jexec "$JAIL" chmod 0700 "/var/db/counter"
mkdir -p "${JROOT}/usr/local/etc/rc.d"
cat >"${JROOT}/usr/local/etc/rc.d/counter" <<'INFRA_RC'
#!/bin/sh
#
# PROVIDE: counter
# REQUIRE: NETWORKING FILESYSTEMS
# KEYWORD: shutdown
#
# Generated by infra for counter; do not hand-edit.
# shellcheck disable=SC2034 # rc.subr reads these variables

. /etc/rc.subr

name="counter"
rcvar="counter_enable"
load_rc_config "$name"
: "${counter_enable:=NO}"

app_user="counter"
envfile="/etc/counter/env"
logfile="/var/log/counter/counter.log"
start_cmd="counter_start"
stop_cmd="counter_stop"
status_cmd="counter_status"
extra_commands="migrate"
migrate_cmd="counter_migrate"
procname="/opt/counter/bin/counter"
pidfile="/var/run/counter/counter.pid"
supervisor_pidfile="/var/run/counter/supervisor.pid"

# The operator's env.
counter_env() {
    [ -r "$envfile" ] || { echo "$name: cannot read $envfile" >&2; return 1; }
    set -a
    # shellcheck disable=SC1090 # the operator's runtime configuration
    . "$envfile"
    HOME=/var/db/counter
    set +a
    # Every variable the app's env.template declares.
    for var in COUNTER_DATABASE_PATH COUNTER_LISTEN_ADDRESS; do
        eval "value=\${$var:-}"
        # shellcheck disable=SC2154 # assigned by the eval above
        case "$value" in
            ''|REPLACE_ME) echo "$name: $var is not set in $envfile" >&2; return 1 ;;
        esac
    done
}

counter_dirs() {
    mkdir -p /var/run/counter /var/log/counter
    chown "$app_user" /var/run/counter /var/log/counter
}

counter_start() {
    counter_dirs
    counter_env || return 1
    echo "Starting $name."
    # daemon -u resets the environment, so the env is sourced again after
    # privileges are dropped; the check above only refuses a bad file.
    /usr/sbin/daemon -c -f -P "$supervisor_pidfile" -p "$pidfile" -o "$logfile" \
        -u "$app_user" -- /bin/sh -c \
        "set -a; . $envfile; HOME=/var/db/counter; set +a; exec $procname serve"
}

counter_stop() {
    stopped=0
    for file in "$supervisor_pidfile" "$pidfile"; do
        [ -f "$file" ] || continue
        pid="$(cat "$file" 2>/dev/null)" || continue
        if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
            [ "$stopped" -eq 1 ] || echo "Stopping $name."
            kill "$pid" 2>/dev/null
            wait_for_pids "$pid"
            stopped=1
        fi
        rm -f "$file"
    done
    [ "$stopped" -eq 1 ] || { echo "$name not running."; return 1; }
}

counter_status() {
    if [ -f "$pidfile" ] && kill -0 "$(cat "$pidfile")" 2>/dev/null; then
        echo "$name is running as pid $(cat "$pidfile")."
    else
        echo "$name is not running."
        return 1
    fi
}

counter_migrate() {
    counter_env || return 1
    su -m "$app_user" -c "$procname migrate" </dev/null
}

run_rc_command "$1"
INFRA_RC
chmod 0755 "${JROOT}/usr/local/etc/rc.d/counter"
jexec "$JAIL" sysrc counter_enable="YES"
if jexec "$JAIL" test -f "/etc/${APP}/env"; then
  jexec "$JAIL" chown "root:${APP}" "/etc/${APP}/env"
  jexec "$JAIL" chmod 0640 "/etc/${APP}/env"
else
  log "No /etc/${APP}/env yet: write it from the app's env.template, root:${APP} 0640, before the first activation"
fi